package com.portfolio.assetory.inquiry.repository;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import com.portfolio.assetory.inquiry.domain.InquiryRoom;
public interface InquiryRoomRepository extends JpaRepository<InquiryRoom,Long>{@Query("select r from InquiryRoom r join fetch r.buyer join fetch r.seller join fetch r.product where r.buyer.id=:userId or r.seller.id=:userId")Page<InquiryRoom> findAllForUser(@Param("userId")Long userId,Pageable pageable);@Query("select r from InquiryRoom r join fetch r.buyer join fetch r.seller join fetch r.product where r.id=:id and (r.buyer.id=:userId or r.seller.id=:userId)")Optional<InquiryRoom> findForParticipant(@Param("id")Long id,@Param("userId")Long userId);Optional<InquiryRoom> findByBuyerIdAndProductIdAndSellerId(Long buyerId,Long productId,Long sellerId);}
